#include "scene/CastScene.h"
#include <iostream>
int main(int argc,char**argv){if(argc<3)return 2;auto s=scene::buildScene(cast::Document::load(argv[1]));if(std::string(argv[2])!="rest")scene::appendAnimations(cast::Document::load(argv[2]),s);if(s.animations.empty()){scene::Animation a;s.animations.push_back(a);}std::cout<<"bones="<<s.skeleton.bones.size()<<" anchors="<<s.muzzleAnchors.size()<<'\n';
 for(float f:{0.f,.5f,1.f}){const auto pose=s.samplePose(0,s.animations[0].durationFrames*f);auto muzzle=scene::resolveMuzzlePosition(s,pose);scene::Vec3 lo{1e9f,1e9f,1e9f},hi{-1e9f,-1e9f,-1e9f};for(const auto&m:s.meshes)for(const auto&v:m.vertices){scene::Vec3 p{};float total=0;for(int k=0;k<4;++k)if(v.weights[k]>0&&v.bones[k]<pose.size()){p+=scene::transformPoint(pose[v.bones[k]]*s.skeleton.bones[v.bones[k]].inverseBind,v.position)*v.weights[k];total+=v.weights[k];}if(total==0)p=v.position;lo={std::min(lo.x,p.x),std::min(lo.y,p.y),std::min(lo.z,p.z)};hi={std::max(hi.x,p.x),std::max(hi.y,p.y),std::max(hi.z,p.z)};}
 std::cout<<f<<" muzzle="<<(muzzle?std::to_string(muzzle->x)+","+std::to_string(muzzle->y)+","+std::to_string(muzzle->z):"none")<<" bounds="<<lo.x<<','<<lo.y<<','<<lo.z<<" : "<<hi.x<<','<<hi.y<<','<<hi.z<<'\n';}return 0;}
